import { html, LitElement } from "lit";
import { customElement, property } from "lit/decorators.js";
import "@shoelace-style/shoelace/dist/components/copy-button/copy-button.js";

import { tailwindStyles } from "./styles/Tailwind";
import { Color } from "./lib/Color";
import { ColorConverterInputEvent } from "./events/ColorConverterInputEvent";

export interface InputValues {
  hexValue?: string;
  rgb255Value?: string;
  rgb01Value?: string;
  hsvValue?: string;
  hslValue?: string;
}

export enum InputType {
  HEX = "HEX",
  RGB255 = "RGB255",
  RGB01 = "RGB01",
  HSV = "HSV",
  HSL = "HSL",
}

const inputTypeToLabel = {
  [InputType.HEX]: "Hex",
  [InputType.RGB255]: "RGB (0-255)",
  [InputType.RGB01]: "RGB (0-1)",
  [InputType.HSV]: "HSV",
  [InputType.HSL]: "HSL",
};

export const inputTypeToInputValueKey = {
  [InputType.HEX]: "hexValue",
  [InputType.RGB255]: "rgb255Value",
  [InputType.RGB01]: "rgb01Value",
  [InputType.HSV]: "hsvValue",
  [InputType.HSL]: "hslValue",
} as Record<InputType, keyof InputValues>;

const colorToString = {
  [InputType.HEX]: (color: Color) => "#" + color.getHex(),
  [InputType.RGB255]: (color: Color) =>
    color.getRGB255().splice(0, 3).toString(),
  [InputType.RGB01]: (color: Color) =>
    color
      .getRGB01()
      .splice(0, 3)
      .map((x) => x.toFixed(3))
      .toString(),
  [InputType.HSV]: (color: Color) =>
    color.getHSV(false).splice(0, 3).toString(),
  [InputType.HSL]: (color: Color) =>
    color.getHSL(false).splice(0, 3).toString(),
};

@customElement("color-converter-input")
export class ColorConverterInput extends LitElement {
  static styles = [tailwindStyles];

  @property()
  type: InputType = InputType.HEX;
  @property({ attribute: false })
  inputValues: InputValues = {};
  @property({ attribute: false })
  color: Color = new Color();

  onValueChange(event: Event) {
    this.dispatchEvent(
      new ColorConverterInputEvent(
        this.type,
        (event.target as HTMLInputElement).value
      )
    );
  }

  render() {
    const value =
      this.inputValues[inputTypeToInputValueKey[this.type]] ??
      colorToString[this.type](this.color);
    return html`
      <div class="flex items-stretch border border-gray-300 rounded bg-white overflow-hidden text-left focus-within:ring-1 focus-within:ring-blue-500">
        <div class="flex-1 px-2 py-0.5">
          <label class="block text-[10px] font-semibold text-gray-500 uppercase tracking-wider">${inputTypeToLabel[this.type]}</label>
          <input
            type="text"
            class="w-full text-xs font-mono text-gray-800 outline-none bg-transparent"
            .value=${value}
            @input=${this.onValueChange}
          />
        </div>
        <div class="flex items-center px-2 bg-gray-50 border-l border-gray-200">
          <sl-copy-button value=${value}></sl-copy-button>
        </div>
      </div>
    `;
  }
}
